package com.qognix.docuflow;
import java.util.*;
public class LocalTools {
  public static List<String> sentences(String t){ List<String> out=new ArrayList<>(); String clean=t.replaceAll("\\s+"," ").trim(); for(String s: clean.split("(?<=[.!?])\\s+")){ s=s.trim(); if(s.length()>35) out.add(s); } return out; }
  public static String summary(String t){ List<String> s=sentences(t); if(s.isEmpty()) return "No readable text found in this PDF."; StringBuilder b=new StringBuilder("On-device summary (add a Gemini key for a full AI summary):\n\n"); int n=Math.min(s.size(),10); for(int i=0;i<n;i++) b.append("• ").append(s.get(i)).append("\n\n"); return b.toString(); }
  public static String mcqs(String t, boolean quiz){ List<String> s=sentences(t); if(s.size()<3) return "Not enough text in this PDF to make questions. Try a longer PDF."; StringBuilder b=new StringBuilder(quiz?"Quiz (on-device mode):\n\n":"MCQs (on-device mode — add a Gemini key for AI MCQs):\n\n"); int count=Math.min(8,s.size()); Random rnd=new Random(42);
    for(int i=0;i<count;i++){ String sent=s.get(i); String[] words=sent.split(" "); String best=""; for(String wd: words){ String c=wd.replaceAll("[^A-Za-z0-9-]",""); if(c.length()>best.length() && c.length()>=6) best=c; } if(best.isEmpty()) continue;
      if(quiz){ b.append("Q").append(i+1).append(": ").append(sent.replace(best,"_____")).append("\nAnswer: ").append(best).append("\n\n"); }
      else { List<String> opts=new ArrayList<>(); opts.add(best); Set<String> used=new HashSet<>(); used.add(best.toLowerCase()); int guard=0; while(opts.size()<4 && guard++<200){ String wd=words[rnd.nextInt(words.length)].replaceAll("[^A-Za-z0-9-]",""); if(wd.length()>=5 && used.add(wd.toLowerCase())) opts.add(wd); } Collections.shuffle(opts,rnd); b.append("Q").append(i+1).append(": ").append(sent.replace(best,"_____")).append("\n"); char ch='A'; for(String o: opts){ b.append(ch++).append(") ").append(o).append("\n"); } b.append("Correct: ").append(best).append("\n\n"); } }
    return b.toString(); }
  public static String ask(String t,String q){ if(q==null||q.trim().isEmpty()) return "Type a question first."; List<String> s=sentences(t); String[] qw=q.toLowerCase().split("\\W+"); List<String> hits=new ArrayList<>(); for(String sent: s){ String low=sent.toLowerCase(); int score=0; for(String w: qw) if(w.length()>2 && low.contains(w)) score++; if(score>=1) hits.add(sent); if(hits.size()>=6) break; } if(hits.isEmpty()) return "No matching part found in this PDF for that question (on-device search). Add a Gemini key for a full AI answer."; StringBuilder b=new StringBuilder("From your PDF:\n\n"); for(String h: hits) b.append("• ").append(h).append("\n\n"); return b.toString(); }
}
